from collections import deque

class Graph:
    def __init__(self, edges):
        # edges is a list of tuples in the form of (src, dest)
        self.graph = self.build_graph(edges)

    # Function to convert direct edges into an adjacency list for simplicity
    def build_graph(self, edges):
        graph = {}
        for src, dest in edges:
            if src in graph:
                graph[src].append(dest)
            else:
                graph[src] = [dest]
        return graph

    def initialize_visited(self):
        self.visited = {node: False for node in self.graph}

    def breadth_first_search(self, source):
        self.initialize_visited()
        queue = deque([source])
        parents = {source: None}
        while queue:
            node = queue.popleft()
            if not self.visited[node]:
                self.visited[node] = True
                for neighbor in self.graph[node]:
                    if not self.visited[neighbor]:
                        queue.append(neighbor)
                        parents[neighbor] = node
        return parents

    def trace_path(self, source, destination):
        parents = self.breadth_first_search(source)
        path, previous_node = [], destination
        while previous_node is not None:
            path.insert(0, previous_node)
            previous_node = parents[previous_node]
        return path if path else None

